<script setup lang="ts">
useSeoPage('Sign in', 'Sign in to manage your 247URL links and analytics.', '/login')
const { login } = useAuth(); const form = reactive({ email: '', password: '', remember: false }); const errors = ref<Record<string,string[]>>({}); const error = ref(''); const loading = ref(false)
async function submit() { loading.value=true; errors.value={}; error.value=''; try { const response = await login(form); await navigateTo(response.data.user.email_verified_at ? '/dashboard' : '/verify-email') } catch (e:any) { errors.value=e?.data?.errors||{}; error.value=e?.data?.message||'Unable to sign in. Please check your connection.' } finally { loading.value=false } }
</script>
<template><AuthShell title="Welcome back" description="Sign in to manage links and understand every click."><form class="grid gap-5" @submit.prevent="submit"><div><label class="label" for="email">Email address</label><input id="email" v-model="form.email" class="input" type="email" autocomplete="email" required :aria-invalid="Boolean(errors.email)"><p class="field-error">{{ errors.email?.[0] }}</p></div><div><div class="flex justify-between"><label class="label" for="password">Password</label><NuxtLink to="/forgot-password" class="text-xs text-brand">Forgot password?</NuxtLink></div><input id="password" v-model="form.password" class="input" type="password" autocomplete="current-password" required></div><label class="flex items-center gap-2 text-xs text-text-secondary"><input v-model="form.remember" type="checkbox" class="size-4 accent-brand">Keep me signed in for 30 days</label><p v-if="error && !Object.keys(errors).length" class="rounded-md border border-danger-border bg-danger-bg p-3 text-sm text-danger" role="alert">{{ error }}</p><button class="btn-primary w-full" :disabled="loading">{{ loading ? 'Signing in…' : 'Sign in' }}</button></form><p class="mt-6 text-center text-sm text-text-secondary">New here? <NuxtLink to="/register" class="font-medium text-brand">Create an account</NuxtLink></p></AuthShell></template>
